Continue until the end of the array is reached.
The final code
function intersect(arr1, arr2) {
  // your code here
  let i = 0; j = 0;
  const result = [];

  while(i < arr1.length && j < arr2.length) {
    if(arr1[i] === arr2[j]) {
      result.push(arr1[i]);
      i++;
      j++;
    } else if(arr1[i] < arr2[j]) {
      i++;
    }
    else {
      j++;
    }
  }
  return result;
}

